/**
 * Types of the precompiled validators in `toolValidators.js` (generated by
 * scripts/gen-coproducer-validators.ts; one export per co-producer tool).
 */

export interface ToolValidationError {
    instancePath: string;
    schemaPath: string;
    keyword: string;
    params: Record<string, unknown>;
    message?: string;
}

export interface CompiledToolValidator {
    (data: unknown): boolean;
    errors?: ToolValidationError[] | null;
}

export declare const validate_get_song: CompiledToolValidator;
export declare const validate_import_song: CompiledToolValidator;
export declare const validate_edit_pattern: CompiledToolValidator;
export declare const validate_set_params: CompiledToolValidator;
export declare const validate_arrange: CompiledToolValidator;
export declare const validate_render_and_measure: CompiledToolValidator;
export declare const validate_export: CompiledToolValidator;
